                      <span className="material-symbols-outlined text-sm text-blue-600">pending</span>
                    </div>
                    <div>
                      <p className="text-xs font-semibold text-zinc-900">En Progreso</p>
                      <p className="text-xs text-zinc-500">Estado actual</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </main>

      {/* Modal Incidencias de la Operación */}
      {showIncidenciasModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="w-full max-w-3xl rounded-xl bg-white p-6 shadow-2xl">
            <div className="mb-4 flex items-center justify-between">
              <div>
                <h3 className="text-lg font-bold text-zinc-900">Incidencias de la Operación</h3>
                <p className="text-sm text-zinc-500">
                  Operación {operacion.codigo} — {incidencias.length} incidencia(s)
                </p>
              </div>
              <button
                onClick={() => setShowIncidenciasModal(false)}
                className="rounded-lg p-2 text-zinc-400 transition-colors hover:bg-zinc-100 hover:text-zinc-700"
              >
                <span className="material-symbols-outlined text-xl">close</span>
              </button>
            </div>

            <div className="max-h-[400px] space-y-2 overflow-y-auto border-t border-b border-zinc-200 py-3">
              {incidenciasLoading ? (
                <p className="px-1 text-sm text-zinc-500">Cargando incidencias...</p>
              ) : incidencias.length === 0 ? (
                <p className="px-1 text-sm text-zinc-500">
                  No hay incidencias registradas para esta operación.
                </p>
              ) : (
                incidencias.map((inc) => (
                  <div
                    key={inc.id_incidencia}
                    className="flex items-start justify-between gap-3 rounded-lg border border-zinc-200 p-3"
                  >
                    <div className="flex items-start gap-3">
                      <div className="mt-1 flex h-8 w-8 items-center justify-center rounded-full bg-red-50">
                        <span className="material-symbols-outlined text-base text-red-600">warning</span>
                      </div>
                      <div>
                        <div className="flex flex-wrap items-center gap-2">
                          <span className="font-mono text-xs font-semibold text-zinc-900">
                            {inc.codigo}
                          </span>
                          <span className="rounded-full bg-zinc-100 px-2 py-0.5 text-xs text-zinc-600">
                            {inc.tipo_incidencia?.nombre || "Sin tipo"}
                          </span>
                          <span className="rounded-full bg-amber-50 px-2 py-0.5 text-xs text-amber-700">
                            Sev. {inc.grado_severidad}
                          </span>
                          <span className="rounded-full bg-zinc-100 px-2 py-0.5 text-xs text-zinc-600">
                            {inc.estado_incidencia?.nombre || "Sin estado"}
                          </span>
                        </div>
                        <p className="mt-1 text-sm text-zinc-700 line-clamp-2">{inc.descripcion}</p>
                        <p className="mt-1 text-xs text-zinc-400">
                          {new Date(inc.fecha_hora).toLocaleString("es-ES")}
                        </p>
                      </div>
                    </div>
                    <div className="flex flex-col items-end gap-2">
                      <Link
                        href={`/monitoreo/incidencias/${inc.id_incidencia}`}
                        className="inline-flex items-center gap-1 rounded-lg border border-zinc-200 px-3 py-1.5 text-xs font-medium text-zinc-700 hover:bg-zinc-50"
                      >
                        <span className="material-symbols-outlined text-sm">visibility</span>
                        Ver detalle
                      </Link>
                    </div>
                  </div>
                ))
              )}
            </div>

            <div className="mt-4 flex items-center justify-between">
              <p className="text-xs text-zinc-500">
                Para gestionar las incidencias en detalle (editar, cerrar, etc.), usa el módulo completo.
              </p>
              <Link
                href="/monitoreo/incidencias"
                className="inline-flex items-center gap-2 rounded-lg bg-orange-600 px-4 py-2 text-xs font-semibold text-white hover:bg-orange-700"
              >
                <span className="material-symbols-outlined text-sm">open_in_new</span>
                Ir al módulo de incidencias
              </Link>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { MapHeader } from "@/components/monitoreo/MapHeader";

const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:3001"; 

interface FormData {
  codigo: string;
  fecha_inicio: string;
  id_estado_operacion: string;
  operador_id: string;
  medio_transporte: "vehiculo" | "buque";
  vehiculo_id: string;
  buque_id: string;
  contenedores: string[];
  descripcion: string;
}

export default function NuevaOperacionPage() {
  const router = useRouter();
  const [saving, setSaving] = useState(false);
  const [estados, setEstados] = useState<any[]>([]);
  const [operadores, setOperadores] = useState<any[]>([]);
  const [vehiculos, setVehiculos] = useState<any[]>([]);
  const [buques, setBuques] = useState<any[]>([]);
  const [contenedoresDisponibles, setContenedoresDisponibles] = useState<any[]>([]);
  const [nuevoContenedor, setNuevoContenedor] = useState("");

  const [formData, setFormData] = useState<FormData>({
    codigo: `OP-${new Date().getFullYear()}-${String(Math.floor(Math.random() * 10000)).padStart(4, "0")}`,
    fecha_inicio: new Date().toISOString().slice(0, 16),
    id_estado_operacion: "",
    operador_id: "",
    medio_transporte: "vehiculo",
    vehiculo_id: "",
    buque_id: "",
    contenedores: [],
    descripcion: "",
  });

  useEffect(() => {
    // Cargar datos iniciales
    const cargarDatos = async () => {
      try {
        // Estados
        const resEstados = await fetch(`${API_URL}/monitoreo/estados`);
        if (resEstados.ok) {
          const dataEstados = await resEstados.json();
          setEstados(Array.isArray(dataEstados) ? dataEstados : []);
          // Seleccionar "Programada" por defecto si existe
          const programada = dataEstados.find((e: any) => e.nombre === "Programada");
          if (programada) {
            setFormData(prev => ({ ...prev, id_estado_operacion: programada.id_estado_operacion }));
          }
        }

        // Operadores
        const resOperadores = await fetch(`${API_URL}/monitoreo/operadores`);
        if (resOperadores.ok) {
          const dataOperadores = await resOperadores.json();
          setOperadores(Array.isArray(dataOperadores) ? dataOperadores : []);
        }

        // Vehículos
        const resVehiculos = await fetch(`${API_URL}/monitoreo/vehiculos`);
        if (resVehiculos.ok) {
          const dataVehiculos = await resVehiculos.json();
          setVehiculos(Array.isArray(dataVehiculos) ? dataVehiculos : []);
        }

        // Buques
        const resBuques = await fetch(`${API_URL}/monitoreo/buques`);
        if (resBuques.ok) {
          const dataBuques = await resBuques.json();
          setBuques(Array.isArray(dataBuques) ? dataBuques : []);
        }

        // Contenedores disponibles (por ahora filtramos por estado Disponible desde el backend)
        const resContenedores = await fetch(`${API_URL}/monitoreo/contenedores?estado=Disponible`);
        if (resContenedores.ok) {
          const dataContenedores = await resContenedores.json();
          setContenedoresDisponibles(Array.isArray(dataContenedores) ? dataContenedores : []);
        }
      } catch (error) {
        console.error("Error cargando datos:", error);
      }
    };

    cargarDatos();
  }, []);

  const handleAddContenedor = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter" && nuevoContenedor.trim()) {
      e.preventDefault();
      if (!formData.contenedores.includes(nuevoContenedor.trim())) {
        setFormData({
          ...formData,
          contenedores: [...formData.contenedores, nuevoContenedor.trim()],
        });
      }
      setNuevoContenedor("");
    }
  };

  const handleRemoveContenedor = (codigo: string) => {
    setFormData({
      ...formData,
      contenedores: formData.contenedores.filter((c) => c !== codigo),
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);

    try {
      const payload: any = {
        codigo: formData.codigo,
        fecha_inicio: formData.fecha_inicio,
        id_estado_operacion: formData.id_estado_operacion,
        operador_id: formData.operador_id,
        medio_transporte: formData.medio_transporte,
        contenedores: formData.contenedores,
        descripcion: formData.descripcion || null,
      };

      if (formData.medio_transporte === "vehiculo" && formData.vehiculo_id) {
        payload.vehiculo_id = formData.vehiculo_id;
      } else if (formData.medio_transporte === "buque" && formData.buque_id) {
        payload.buque_id = formData.buque_id;
      }

      const response = await fetch(`${API_URL}/monitoreo/operaciones`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      if (response.ok) {
        const operacionCreada = await response.json();
        router.push(`/monitoreo/operaciones/${operacionCreada.id_operacion}`);
      } else {
        const error = await response.json();
        alert(`Error: ${error.message || "No se pudo crear la operación"}`);
      }
    } catch (error) {
      console.error("Error al crear operación:", error);
      alert("Error al crear la operación");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="flex h-screen w-full flex-col overflow-hidden">
      <MapHeader />

      <main className="flex-1 overflow-y-auto bg-zinc-50 p-6">
          {/* Header */}
          <div className="mb-6 mx-auto max-w-5xl">
            <Link
              href="/monitoreo/operaciones"
              className="mb-2 inline-flex items-center gap-1 text-sm text-zinc-600 hover:text-primary"
            >
              <span className="material-symbols-outlined text-lg">arrow_back</span>
              Volver a Operaciones
            </Link>
            <h1 className="text-3xl font-bold text-zinc-900">Crear Nueva Operación</h1>
            <p className="mt-1 text-sm text-zinc-500">Completa el formulario para crear una nueva operación de monitoreo</p>
          </div>

          <form onSubmit={handleSubmit} className="mx-auto max-w-5xl">
            <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
              {/* Columna Principal (2/3) */}
              <div className="lg:col-span-2 space-y-6">
                {/* Información General */}
                <div className="rounded-xl border border-zinc-200 bg-white shadow-sm">
                  <div className="border-b border-zinc-200 p-6">
                    <h2 className="text-lg font-bold text-zinc-900">Información General</h2>
                  </div>
                  <div className="space-y-6 p-6">
                    <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                      {/* Código */}
                      <div>
                        <label htmlFor="codigo" className="mb-2 block text-sm font-semibold text-zinc-900">
                          Código de Operación
                        </label>
                        <input
                          type="text"
                          id="codigo"
                          disabled
                          value={formData.codigo}
                          className="h-11 w-full rounded-lg border border-zinc-300 bg-zinc-50 px-4 text-sm text-zinc-500"
                        />
                        <p className="mt-1 text-xs text-zinc-500">Generado automáticamente</p>
                      </div>

                      {/* Fecha de Inicio */}
                      <div>
                        <label htmlFor="fecha_inicio" className="mb-2 block text-sm font-semibold text-zinc-900">
                          Fecha de Inicio <span className="text-red-500">*</span>
                        </label>
                        <input
                          type="datetime-local"
                          id="fecha_inicio"
                          required
                          value={formData.fecha_inicio}
                          onChange={(e) => setFormData({ ...formData, fecha_inicio: e.target.value })}
                          className="h-11 w-full rounded-lg border border-zinc-300 bg-white px-4 text-sm text-zinc-900 transition-colors focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                        />
                      </div>
                    </div>

                    {/* Estado */}
                    <div>
                      <label htmlFor="estado" className="mb-2 block text-sm font-semibold text-zinc-900">
                        Estado Inicial <span className="text-red-500">*</span>
                      </label>
                      <select
                        id="estado"
                        required
                        value={formData.id_estado_operacion}
                        onChange={(e) => setFormData({ ...formData, id_estado_operacion: e.target.value })}
                        className="h-11 w-full rounded-lg border border-zinc-300 bg-white px-4 text-sm text-zinc-900 transition-colors focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                      >
                        <option value="">Selecciona un estado</option>
                        {estados.map((estado) => (
                          <option key={estado.id_estado_operacion} value={estado.id_estado_operacion}>
                            {estado.nombre}
                          </option>
                        ))}
                      </select>
                    </div>

                    {/* Descripción */}
                    <div>
                      <label htmlFor="descripcion" className="mb-2 block text-sm font-semibold text-zinc-900">
                        Descripción
                      </label>
                      <textarea
                        id="descripcion"
                        rows={4}
                        value={formData.descripcion}
                        onChange={(e) => setFormData({ ...formData, descripcion: e.target.value })}
                        className="w-full rounded-lg border border-zinc-300 bg-white px-4 py-3 text-sm text-zinc-900 transition-colors placeholder:text-zinc-400 focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                        placeholder="Detalles adicionales de la operación..."
                      />
                    </div>
                  </div>
                </div>

                {/* Transporte */}
                <div className="rounded-xl border border-zinc-200 bg-white shadow-sm">
                  <div className="border-b border-zinc-200 p-6">
                    <h2 className="text-lg font-bold text-zinc-900">Medio de Transporte</h2>
                  </div>
                  <div className="space-y-6 p-6">
                    {/* Tipo de Transporte */}
                    <div>
                      <label className="mb-3 block text-sm font-semibold text-zinc-900">Tipo de Transporte</label>
                      <div className="flex gap-4">
                        <label className="flex flex-1 cursor-pointer items-center gap-3 rounded-lg border-2 border-zinc-300 p-4 transition-all has-[:checked]:border-primary has-[:checked]:bg-primary/5">
                          <input
                            type="radio"
                            name="medio_transporte"
                            value="vehiculo"
                            checked={formData.medio_transporte === "vehiculo"}
                            onChange={(e) => setFormData({ ...formData, medio_transporte: e.target.value as "vehiculo" | "buque", vehiculo_id: "", buque_id: "" })}
                            className="h-4 w-4 border-zinc-300 text-primary focus:ring-primary"
                          />
                          <div className="flex items-center gap-2">
                            <span className="material-symbols-outlined text-2xl">local_shipping</span>
                            <span className="text-sm font-semibold">Vehículo</span>
                          </div>
                        </label>
                        <label className="flex flex-1 cursor-pointer items-center gap-3 rounded-lg border-2 border-zinc-300 p-4 transition-all has-[:checked]:border-primary has-[:checked]:bg-primary/5">
                          <input
                            type="radio"
                            name="medio_transporte"
                            value="buque"
                            checked={formData.medio_transporte === "buque"}
                            onChange={(e) => setFormData({ ...formData, medio_transporte: e.target.value as "vehiculo" | "buque", vehiculo_id: "", buque_id: "" })}
                            className="h-4 w-4 border-zinc-300 text-primary focus:ring-primary"
                          />
                          <div className="flex items-center gap-2">
                            <span className="material-symbols-outlined text-2xl">sailing</span>
                            <span className="text-sm font-semibold">Buque</span>
                          </div>
                        </label>
                      </div>
                    </div>

                    {/* Selector */}
                    {formData.medio_transporte === "vehiculo" ? (
                      <div>
                        <label htmlFor="vehiculo" className="mb-2 block text-sm font-semibold text-zinc-900">
                          Seleccionar Vehículo
                        </label>
                        <select
                          id="vehiculo"
                          value={formData.vehiculo_id}
                          onChange={(e) => setFormData({ ...formData, vehiculo_id: e.target.value })}
                          className="h-11 w-full rounded-lg border border-zinc-300 bg-white px-4 text-sm text-zinc-900 transition-colors focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                        >
                          <option value="">Selecciona un vehículo</option>
                          {vehiculos.map((vehiculo) => (
                            <option key={vehiculo.id_vehiculo} value={vehiculo.id_vehiculo}>
                              {vehiculo.placa} - {vehiculo.modelo || "Vehículo"}
                            </option>
                          ))}
                        </select>
                      </div>
                    ) : (
                      <div>
                        <label htmlFor="buque" className="mb-2 block text-sm font-semibold text-zinc-900">
                          Seleccionar Buque
                        </label>
                        <select
                          id="buque"
                          value={formData.buque_id}
                          onChange={(e) => setFormData({ ...formData, buque_id: e.target.value })}
                          className="h-11 w-full rounded-lg border border-zinc-300 bg-white px-4 text-sm text-zinc-900 transition-colors focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                        >
                          <option value="">Selecciona un buque</option>
                          {buques.map((buque) => (
                            <option key={buque.id_buque} value={buque.id_buque}>
                              {buque.nombre} - {buque.matricula}
                            </option>
                          ))}
                        </select>
                      </div>
                    )}
                  </div>
                </div>

                {/* Contenedores */}
                <div className="rounded-xl border border-zinc-200 bg-white shadow-sm">
                  <div className="border-b border-zinc-200 p-6">
                    <h2 className="text-lg font-bold text-zinc-900">Contenedores</h2>
                    <p className="text-sm text-zinc-500">Selecciona contenedores disponibles o escribe el código y presiona Enter</p>
                  </div>
                  <div className="p-6">
                    {/* Selector de contenedores disponibles */}
                    <div className="mb-4">
                      <label className="mb-2 block text-sm font-semibold text-zinc-900">
                        Contenedores disponibles
                      </label>
                      <select
                        className="h-11 w-full rounded-lg border border-zinc-300 bg-white px-4 text-sm text-zinc-900 transition-colors focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                        defaultValue=""
                        onChange={(e) => {
                          const codigo = e.target.value;
                          if (codigo && !formData.contenedores.includes(codigo)) {
                            setFormData({
                              ...formData,
                              contenedores: [...formData.contenedores, codigo],
                            });
                          }
                          e.target.value = "";
                        }}
                      >
                        <option value="">Selecciona un contenedor para agregar</option>
                        {contenedoresDisponibles.map((c) => (
                          <option key={c.id_contenedor} value={c.codigo}>
                            {c.codigo} {c.tipo_contenedor?.nombre ? `- ${c.tipo_contenedor.nombre}` : ""}
                          </option>
                        ))}
                      </select>
                    </div>

                    <div className="relative w-full rounded-lg border-2 border-zinc-300 bg-white p-3 focus-within:border-primary focus-within:ring-2 focus-within:ring-primary/20">
                      <div className="flex flex-wrap items-center gap-2">
                        {formData.contenedores.map((codigo) => (
                          <span
                            key={codigo}
                            className="inline-flex items-center gap-2 rounded-lg bg-primary/10 px-3 py-1.5 text-xs font-semibold text-primary"
                          >
                            <span className="material-symbols-outlined text-sm">inventory_2</span>
                            {codigo}
                            <button
                              type="button"
                              onClick={() => handleRemoveContenedor(codigo)}
                              className="text-primary/70 hover:text-primary"
                            >
                              <span className="material-symbols-outlined text-sm">close</span>
                            </button>
                          </span>
                        ))}
                        <input
                          type="text"
                          placeholder={formData.contenedores.length === 0 ? "Escribe código y presiona Enter..." : "Agregar más..."}
                          value={nuevoContenedor}
                          onChange={(e) => setNuevoContenedor(e.target.value)}
                          onKeyDown={handleAddContenedor}
                          className="min-w-[200px] flex-1 border-0 bg-transparent p-0 text-sm text-zinc-900 placeholder-zinc-400 focus:outline-none focus:ring-0"
                        />
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              {/* Columna Lateral (1/3) */}
              <div className="space-y-6">
                {/* Operador */}
                <div className="rounded-xl border border-zinc-200 bg-white shadow-sm">
                  <div className="border-b border-zinc-200 p-6">
                    <h2 className="text-lg font-bold text-zinc-900">Operador</h2>
                  </div>
                  <div className="p-6">
                    <label htmlFor="operador" className="mb-2 block text-sm font-semibold text-zinc-900">
                      Operador Responsable <span className="text-red-500">*</span>
                    </label>
                    <select
                      id="operador"
                      required
                      value={formData.operador_id}
                      onChange={(e) => setFormData({ ...formData, operador_id: e.target.value })}
                      className="h-11 w-full rounded-lg border border-zinc-300 bg-white px-4 text-sm text-zinc-900 transition-colors focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                    >
                      <option value="">Selecciona un operador</option>
                      {operadores.map((operador) => (
                        <option key={operador.id_operador} value={operador.id_operador}>
                          {operador.empleado?.nombre || operador.turno || `Operador ${operador.id_operador.substring(0, 8)}`}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                {/* Resumen */}
                <div className="rounded-xl border border-zinc-200 bg-gradient-to-br from-primary/5 to-primary/10 p-6 shadow-sm">
                  <h3 className="mb-4 text-sm font-bold text-zinc-900">Resumen</h3>
                  <div className="space-y-3 text-sm">
                    <div className="flex items-center justify-between">
                      <span className="text-zinc-600">Contenedores</span>
                      <span className="font-semibold text-zinc-900">{formData.contenedores.length}</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-zinc-600">Transporte</span>
                      <span className="font-semibold text-zinc-900">
                        {formData.medio_transporte === "vehiculo" ? "Vehículo" : "Buque"}
                      </span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="text-zinc-600">Estado</span>
                      <span className="font-semibold text-zinc-900">
                        {estados.find(e => e.id_estado_operacion === formData.id_estado_operacion)?.nombre || "-"}
                      </span>
                    </div>
                  </div>
                </div>

                {/* Botones */}
                <div className="space-y-3">
                  <button
                    type="submit"
                    disabled={saving}
                    className="flex w-full items-center justify-center gap-2 rounded-lg bg-orange-500 px-4 py-3 text-sm font-semibold text-white shadow-lg transition-all hover:bg-orange-600 hover:shadow-xl disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    {saving ? (
                      <>
                        <div className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent"></div>
                        Creando...
                      </>
                    ) : (
                      <>
                        <span className="material-symbols-outlined text-lg">check_circle</span>
                        Crear Operación
                      </>
                    )}
                  </button>
                  <Link
                    href="/monitoreo/operaciones"
                    className="flex w-full items-center justify-center gap-2 rounded-lg border border-zinc-300 bg-white px-4 py-3 text-sm font-semibold text-zinc-700 transition-colors hover:bg-zinc-50"
                  >
                    Cancelar
                  </Link>
                </div>
              </div>
            </div>
          </form>
        </main>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { MapHeader } from "@/components/monitoreo/MapHeader";

const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:3001"; 

interface Operacion {
  id_operacion: string;
  codigo: string;
  fecha_inicio: string;
  fecha_fin: string | null;
  estado_operacion: {
    nombre: string;
  };
  operador?: {
    nombre: string;
  };
  vehiculo?: {
    placa: string;
  };
  buque?: {
    nombre: string;
  };
  contenedores?: any[];
  contenedores_count?: number;
}

export default function OperacionesPage() {
  const [operaciones, setOperaciones] = useState<Operacion[]>([]);
  const [loading, setLoading] = useState(true);
  const [filtroEstado, setFiltroEstado] = useState("");
  const [mostrarFiltroEstado, setMostrarFiltroEstado] = useState(false);
  const [busqueda, setBusqueda] = useState("");
  const [paginaActual, setPaginaActual] = useState(1);
  const [operacionAFinalizar, setOperacionAFinalizar] = useState<string | null>(null);
  const [operacionAEliminar, setOperacionAEliminar] = useState<string | null>(null);
  const [estadosDisponibles, setEstadosDisponibles] = useState<string[]>(["Todos"]);
  const operacionesPorPagina = 10;

  // Cargar estados disponibles desde el backend
  useEffect(() => {
    fetch(`${API_URL}/monitoreo/estados`)
      .then((res) => res.json())
      .then((data) => {
        if (Array.isArray(data)) {
          const nombres = data.map((e: any) => e.nombre);
          setEstadosDisponibles(["Todos", ...nombres]);
        }
      })
      .catch((err) => console.error("Error cargando estados:", err));
  }, []);

  useEffect(() => {
    const url = filtroEstado && filtroEstado !== "Todos"
      ? `${API_URL}/monitoreo/operaciones?estado=${filtroEstado}`
      : `${API_URL}/monitoreo/operaciones`;

    fetch(url)
      .then((res) => res.json())
      .then((data) => {
        setOperaciones(Array.isArray(data) ? data : []);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching operaciones:", err);
        setOperaciones([]);
        setLoading(false);
      });
  }, [filtroEstado]);

  const getEstadoBadge = (estado: string) => {
    const key = (estado || "").toLowerCase();

    const badges: Record<string, { bg: string; text: string; dot: string }> = {
      // Programada
      "programada": { bg: "bg-purple-50", text: "text-purple-700", dot: "bg-purple-500" },
      // En Curso
      "en curso": { bg: "bg-blue-50", text: "text-blue-700", dot: "bg-blue-500" },
      // Completada
      "completada": { bg: "bg-green-50", text: "text-green-700", dot: "bg-green-500" },
      // Cancelada
      "cancelada": { bg: "bg-red-50", text: "text-red-700", dot: "bg-red-500" },
      // En Espera
      "en espera": { bg: "bg-amber-50", text: "text-amber-700", dot: "bg-amber-500" },
    };

    const badge = badges[key] || { bg: "bg-gray-50", text: "text-gray-700", dot: "bg-gray-500" };
    return badge;
  };

  const finalizarOperacion = async (id: string) => {
    try {
      const response = await fetch(`${API_URL}/monitoreo/operaciones/${id}/finalizar`, {
        method: 'PATCH',
      });
      if (response.ok) {
        // Recargar operaciones
        const url = filtroEstado && filtroEstado !== "Todos"
          ? `${API_URL}/monitoreo/operaciones?estado=${filtroEstado}`
          : `${API_URL}/monitoreo/operaciones`;
        const data = await fetch(url).then(res => res.json());
        setOperaciones(Array.isArray(data) ? data : []);
        setOperacionAFinalizar(null);
      } else {
        const errorText = await response.text();
        alert(errorText || 'No se pudo finalizar la operación.');
      }
    } catch (error) {
      console.error("Error al finalizar operación:", error);
    }
  };

  const eliminarOperacion = async (id: string) => {
    try {
      const response = await fetch(`${API_URL}/monitoreo/operaciones/${id}`, {
        method: 'DELETE',
      });
      if (response.ok) {
        // Recargar operaciones
        const url = filtroEstado && filtroEstado !== "Todos"
          ? `${API_URL}/monitoreo/operaciones?estado=${filtroEstado}`
          : `${API_URL}/monitoreo/operaciones`;
        const data = await fetch(url).then(res => res.json());
        setOperaciones(Array.isArray(data) ? data : []);
        setOperacionAEliminar(null);
      }
    } catch (error) {
      console.error("Error al eliminar operación:", error);
    }
  };

  // Filtrar por búsqueda
  const operacionesFiltradas = operaciones.filter((op) => {
    if (!busqueda) return true;
    const searchLower = busqueda.toLowerCase();
    return (
      op.codigo.toLowerCase().includes(searchLower) ||
      op.estado_operacion.nombre.toLowerCase().includes(searchLower) ||
      op.operador?.nombre.toLowerCase().includes(searchLower) ||
      op.vehiculo?.placa.toLowerCase().includes(searchLower) ||
      op.buque?.nombre.toLowerCase().includes(searchLower)
    );
  });

  // Paginación
  const indexUltimo = paginaActual * operacionesPorPagina;
  const indexPrimero = indexUltimo - operacionesPorPagina;
  const operacionesActuales = operacionesFiltradas.slice(indexPrimero, indexUltimo);
  const totalPaginas = Math.ceil(operacionesFiltradas.length / operacionesPorPagina);

  return (
    <div className="flex h-screen w-full flex-col overflow-hidden">
      <MapHeader />

      <main className="flex-1 overflow-y-auto bg-zinc-50 p-6">
          {/* Header: Título + Botón */}
          <div className="mb-6 flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-zinc-900">Operaciones de Monitoreo</h1>
              <p className="mt-1 text-sm text-zinc-500">Gestiona y monitorea todas las operaciones activas</p>
            </div>
            <Link
              href="/monitoreo/operaciones/nueva"
              className="flex h-11 items-center gap-2 rounded-lg bg-orange-500 px-6 text-sm font-semibold text-white shadow-lg transition-all hover:bg-orange-600 hover:shadow-xl"
            >
              <span className="material-symbols-outlined text-xl">add_circle</span>
              <span>Nueva Operación</span>
            </Link>
          </div>

          {/* Filtros */}
          <div className="mb-4 flex flex-wrap items-center gap-3">
            {/* Filtro de Estado */}
            <div className="relative">
              <button
                onClick={() => setMostrarFiltroEstado(!mostrarFiltroEstado)}
                className="flex h-10 items-center gap-2 rounded-lg border border-zinc-300 bg-white px-4 text-sm font-medium text-zinc-700 shadow-sm transition-colors hover:bg-zinc-50"
              >
                <span className="material-symbols-outlined text-lg">filter_list</span>
                <span>Estado: {filtroEstado || "Todos"}</span>
                <span className="material-symbols-outlined text-lg text-zinc-400">expand_more</span>
              </button>
              {mostrarFiltroEstado && (
                <div className="absolute left-0 top-12 z-10 w-48 rounded-lg border border-zinc-200 bg-white py-2 shadow-lg">
                  {estadosDisponibles.map((estado: string) => (
                    <button
                      key={estado}
                      onClick={() => {
                        setFiltroEstado(estado === "Todos" ? "" : estado);
                        setMostrarFiltroEstado(false);
                        setPaginaActual(1);
                      }}
                      className={`w-full px-4 py-2 text-left text-sm transition-colors hover:bg-zinc-100 ${
                        (filtroEstado === estado || (!filtroEstado && estado === "Todos"))
                          ? "bg-primary/10 font-medium text-primary"
                          : "text-zinc-700"
                      }`}
                    >
                      {estado}
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* Búsqueda */}
            <div className="flex-1">
              <div className="relative max-w-md">
                <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-xl text-zinc-400">search</span>
                <input
                  type="text"
                  value={busqueda}
                  onChange={(e) => {
                    setBusqueda(e.target.value);
                    setPaginaActual(1); // Reset a página 1 al buscar
                  }}
                  placeholder="Buscar por código, estado, operador..."
                  className="h-10 w-full rounded-lg border border-zinc-300 bg-white pl-10 pr-4 text-sm text-zinc-700 shadow-sm transition-colors placeholder:text-zinc-400 focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                />
              </div>
            </div>

            {filtroEstado && (
              <button
                onClick={() => setFiltroEstado("")}
                className="flex h-10 items-center gap-2 rounded-lg px-4 text-sm font-medium text-red-600 transition-colors hover:bg-red-50"
              >
                <span className="material-symbols-outlined text-lg">close</span>
                <span>Limpiar filtros</span>
              </button>
            )}
          </div>

          {/* Tabla */}
          <div className="overflow-hidden rounded-xl border border-zinc-200 bg-white shadow-sm">
            <div className="overflow-x-auto">
              <table className="min-w-full text-sm">
                <thead className="bg-zinc-50">
                  <tr>
                    <th className="px-4 py-3 text-left font-semibold text-zinc-600">Código</th>
                    <th className="px-4 py-3 text-left font-semibold text-zinc-600">Fecha Inicio</th>
                    <th className="px-4 py-3 text-left font-semibold text-zinc-600">Estado</th>
                    <th className="px-4 py-3 text-left font-semibold text-zinc-600">Operador</th>
                    <th className="px-4 py-3 text-left font-semibold text-zinc-600">Medio de Transporte</th>
                    <th className="px-4 py-3 text-left font-semibold text-zinc-600"># Contenedores</th>
                    <th className="px-4 py-3 text-left font-semibold text-zinc-600">Acciones</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-zinc-200">
                  {loading ? (
                    <tr>
                      <td colSpan={7} className="px-4 py-8 text-center text-sm text-zinc-500">
                        Cargando...
                      </td>
                    </tr>
                  ) : operaciones.length === 0 ? (
                    <tr>
                      <td colSpan={7} className="px-4 py-8 text-center text-sm text-zinc-500">
                        No hay operaciones disponibles
                      </td>
                    </tr>
                  ) : (
                    operacionesActuales.map((operacion) => {
                      const badge = getEstadoBadge(operacion.estado_operacion.nombre);
                      const medioTransporte = operacion.buque ? "Marítimo" : "Terrestre";
                      const iconoTransporte = operacion.buque ? "sailing" : "local_shipping";

                      return (
                        <tr key={operacion.id_operacion} className="transition-colors hover:bg-zinc-50">
                          <td className="whitespace-nowrap px-4 py-3 font-medium text-zinc-800">
                            {operacion.codigo}
                          </td>
                          <td className="whitespace-nowrap px-4 py-3 text-zinc-600">
                            {new Date(operacion.fecha_inicio).toLocaleDateString("es-ES", {
                              day: "2-digit",
                              month: "2-digit",
                              year: "numeric",
                              hour: "2-digit",
                              minute: "2-digit",
                            })}
                          </td>
                          <td className="whitespace-nowrap px-4 py-3">
                            <span className={`inline-flex items-center gap-1.5 rounded-full ${badge.bg} px-3 py-1 text-xs font-semibold ${badge.text}`}>
                              <span className={`h-2 w-2 rounded-full ${badge.dot}`}></span>
                              {operacion.estado_operacion.nombre}
                            </span>
                          </td>
                          <td className="whitespace-nowrap px-4 py-3 text-zinc-600">
                            {operacion.operador?.nombre || "Sin asignar"}
                          </td>
                          <td className="whitespace-nowrap px-4 py-3 text-zinc-600">
                            <div className="flex items-center gap-2">
                              <span className="material-symbols-outlined text-lg">{iconoTransporte}</span>
                              <span>{medioTransporte}</span>
                            </div>
                          </td>
                          <td className="whitespace-nowrap px-4 py-3 text-zinc-600">
                            {operacion.contenedores_count ?? operacion.contenedores?.length ?? 0}
                          </td>
                          <td className="whitespace-nowrap px-4 py-3">
                            <div className="flex items-center gap-1">
                              <Link
                                href={`/monitoreo/operaciones/${operacion.id_operacion}`}
                                className="flex h-9 w-9 items-center justify-center rounded-lg text-zinc-600 transition-colors hover:bg-blue-50 hover:text-blue-600"
                                title="Ver detalle"
                              >
                                <span className="material-symbols-outlined text-xl">visibility</span>
                              </Link>
                              <Link
                                href={`/monitoreo/operaciones/${operacion.id_operacion}/editar`}
                                className="flex h-9 w-9 items-center justify-center rounded-lg text-zinc-600 transition-colors hover:bg-amber-50 hover:text-amber-600"
                                title="Editar"
                              >
                                <span className="material-symbols-outlined text-xl">edit</span>
                              </Link>
                              {(() => {
                                const estado = (operacion.estado_operacion.nombre || '').toLowerCase();
                                const puedeFinalizar = estado === 'en curso' || estado === 'en espera';
                                return (
                                  puedeFinalizar && (
                                    <button
                                      onClick={() => setOperacionAFinalizar(operacion.id_operacion)}
                                      className="flex h-9 w-9 items-center justify-center rounded-lg text-zinc-600 transition-colors hover:bg-green-50 hover:text-green-600"
                                      title="Finalizar operación"
                                    >
                                      <span className="material-symbols-outlined text-xl">task_alt</span>
                                    </button>
                                  )
                                );
                              })()}
                              <button
                                onClick={() => setOperacionAEliminar(operacion.id_operacion)}
                                className="flex h-9 w-9 items-center justify-center rounded-lg text-zinc-600 transition-colors hover:bg-red-50 hover:text-red-600"
                                title="Eliminar"
                              >
                                <span className="material-symbols-outlined text-xl">delete</span>
                              </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>

            {/* Paginación */}
            <div className="flex items-center justify-between border-t border-zinc-200 px-4 py-3">
              <p className="text-sm text-zinc-600">
                Mostrando <span className="font-medium">{indexPrimero + 1}</span> a{" "}
                <span className="font-medium">{Math.min(indexUltimo, operacionesFiltradas.length)}</span> de{" "}
                <span className="font-medium">{operacionesFiltradas.length}</span> resultados
                {busqueda && <span className="ml-1 text-zinc-400">(filtrado de {operaciones.length})</span>}
              </p>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setPaginaActual(Math.max(1, paginaActual - 1))}
                  disabled={paginaActual === 1}
                  className="flex h-8 w-8 items-center justify-center rounded-lg border border-zinc-300 bg-white text-zinc-600 shadow-sm transition-colors hover:bg-zinc-50 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <span className="material-symbols-outlined text-xl">chevron_left</span>
                </button>
                <div className="flex items-center gap-1">
                  {(() => {
                    const maxVisibles = 5;
                    if (totalPaginas <= maxVisibles) {
                      return Array.from({ length: totalPaginas }, (_, i) => i + 1).map((numPagina) => (
                        <button
                          key={numPagina}
                          onClick={() => setPaginaActual(numPagina)}
                          className={`flex h-8 w-8 items-center justify-center rounded-lg text-sm font-medium shadow-sm transition-colors ${
                            paginaActual === numPagina
                              ? "border border-primary bg-primary/10 text-primary"
                              : "border border-transparent text-zinc-600 hover:bg-zinc-100"
                          }`}
                        >
                          {numPagina}
                        </button>
                      ));
                    }

                    // Calcular ventana móvil alrededor de la página actual
                    const start = Math.max(1, Math.min(paginaActual - 2, totalPaginas - maxVisibles + 1));
                    const end = Math.min(totalPaginas, start + maxVisibles - 1);
                    const paginas = [] as number[];
                    for (let p = start; p <= end; p++) paginas.push(p);

                    return (
                      <>
                        {start > 1 && (
                          <>
                            <button
                              onClick={() => setPaginaActual(1)}
                              className={`flex h-8 w-8 items-center justify-center rounded-lg text-sm font-medium shadow-sm transition-colors ${
                                paginaActual === 1
                                  ? "border border-primary bg-primary/10 text-primary"
                                  : "border border-transparent text-zinc-600 hover:bg-zinc-100"
                              }`}
                            >
                              1
                            </button>
                            {start > 2 && <span className="text-zinc-400">...</span>}
                          </>
                        )}

                        {paginas.map((numPagina) => (
                          <button
                            key={numPagina}
                            onClick={() => setPaginaActual(numPagina)}
                            className={`flex h-8 w-8 items-center justify-center rounded-lg text-sm font-medium shadow-sm transition-colors ${
                              paginaActual === numPagina
                                ? "border border-primary bg-primary/10 text-primary"
                                : "border border-transparent text-zinc-600 hover:bg-zinc-100"
                            }`}
                          >
                            {numPagina}
                          </button>
                        ))}

                        {end < totalPaginas && (
                          <>
                            {end < totalPaginas - 1 && <span className="text-zinc-400">...</span>}
                            <button
                              onClick={() => setPaginaActual(totalPaginas)}
                              className={`flex h-8 w-8 items-center justify-center rounded-lg text-sm font-medium shadow-sm transition-colors ${
                                paginaActual === totalPaginas
                                  ? "border border-primary bg-primary/10 text-primary"
                                  : "border border-transparent text-zinc-600 hover:bg-zinc-100"
                              }`}
                            >
                              {totalPaginas}
                            </button>
                          </>
                        )}
                      </>
                    );
                  })()}
                </div>
                <button
                  onClick={() => setPaginaActual(Math.min(totalPaginas, paginaActual + 1))}
                  disabled={paginaActual === totalPaginas}
                  className="flex h-8 w-8 items-center justify-center rounded-lg border border-zinc-300 bg-white text-zinc-600 shadow-sm transition-colors hover:bg-zinc-50 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <span className="material-symbols-outlined text-xl">chevron_right</span>
                </button>
              </div>
            </div>
          </div>
        </main>

      {/* Modal de Confirmación - Finalizar */}
      {operacionAFinalizar && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="w-full max-w-md rounded-xl bg-white p-6 shadow-2xl">
            <div className="mb-4 flex items-center gap-3">
              <div className="flex h-12 w-12 items-center justify-center rounded-full bg-green-100">
                <span className="material-symbols-outlined text-2xl text-green-600">task_alt</span>
              </div>
              <div>
                <h3 className="text-lg font-bold text-zinc-900">Finalizar Operación</h3>
                <p className="text-sm text-zinc-500">Esta acción no se puede deshacer</p>
              </div>
            </div>
            <p className="mb-6 text-sm text-zinc-600">
              ¿Estás seguro de que deseas marcar esta operación como completada? Se actualizará el estado y no podrás revertir esta acción.
            </p>
            <div className="flex gap-3">
              <button
                onClick={() => setOperacionAFinalizar(null)}
                className="flex-1 rounded-lg border border-zinc-300 bg-white px-4 py-2.5 text-sm font-semibold text-zinc-700 transition-colors hover:bg-zinc-50"
              >
                Cancelar
              </button>
              <button
                onClick={() => finalizarOperacion(operacionAFinalizar)}
                className="flex-1 rounded-lg bg-green-600 px-4 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-green-700"
              >
                Confirmar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal de Confirmación - Eliminar */}
      {operacionAEliminar && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="w-full max-w-md rounded-xl bg-white p-6 shadow-2xl">
            <div className="mb-4 flex items-center gap-3">
              <div className="flex h-12 w-12 items-center justify-center rounded-full bg-red-100">
                <span className="material-symbols-outlined text-2xl text-red-600">warning</span>
              </div>
              <div>
                <h3 className="text-lg font-bold text-zinc-900">Eliminar Operación</h3>
                <p className="text-sm text-zinc-500">Esta acción no se puede deshacer</p>
              </div>
            </div>
            <p className="mb-6 text-sm text-zinc-600">
              ¿Estás seguro de que deseas eliminar esta operación? Se eliminarán todos los datos asociados y no podrás recuperarlos.
            </p>
            <div className="flex gap-3">
              <button
                onClick={() => setOperacionAEliminar(null)}
                className="flex-1 rounded-lg border border-zinc-300 bg-white px-4 py-2.5 text-sm font-semibold text-zinc-700 transition-colors hover:bg-zinc-50"
              >
                Cancelar
              </button>
              <button
                onClick={() => eliminarOperacion(operacionAEliminar)}
                className="flex-1 rounded-lg bg-red-600 px-4 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-red-700"
              >
                Eliminar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

