"use client";

import { useMemo, useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { operacionesAPI, OperacionMaritima, PaginatedResponse } from "@/lib/api/operaciones-maritimas";

type OperationStatus =
  | "Completada"
  | "En Curso"
  | "Programada"
  | "Cancelada"
  | "En Espera"
  | "Desconocido";

const statusBadgeStyles: Record<
  OperationStatus,
  { light: string; dark: string }
> = {
  Completada: {
    light: "bg-[#d1fae5] text-[#065f46]",
    dark: "dark:bg-[#064e3b] dark:text-[#a7f3d0]",
  },
  "En Curso": {
    light: "bg-[#fef3c7] text-[#92400e]",
    dark: "dark:bg-[#92400e] dark:text-[#fde68a]",
  },
  Programada: {
    light: "bg-[#dbeafe] text-[#1e40af]",
    dark: "dark:bg-[#1e3a8a] dark:text-[#bfdbfe]",
  },
  Cancelada: {
    light: "bg-[#fee2e2] text-[#991b1b]",
    dark: "dark:bg-[#991b1b] dark:text-[#fecaca]",
  },
  "En Espera": {
    light: "bg-[#f3f4f6] text-[#6b7280]",
    dark: "dark:bg-[#374151] dark:text-[#d1d5db]",
  },
  Desconocido: {
    light: "bg-[#f3f4f6] text-[#6b7280]",
    dark: "dark:bg-[#374151] dark:text-[#d1d5db]",
  },
};

export default function RegistrarIncidenciaPage() {
  const [selectedCode, setSelectedCode] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [operationsData, setOperationsData] = useState<PaginatedResponse<OperacionMaritima> | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const router = useRouter();

  useEffect(() => {
    fetchOperations();
  }, [currentPage]);

  const fetchOperations = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await operacionesAPI.getOperaciones(currentPage, 10);
      setOperationsData(data);
      
      // Set default selection if no operation is selected
      if (!selectedCode && data.data.length > 0) {
        setSelectedCode(data.data[0].code);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Error al cargar operaciones");
    } finally {
      setLoading(false);
    }
  };

  const filteredOperations = useMemo(() => {
    if (!operationsData || !query.trim()) return operationsData?.data || [];
    const lower = query.toLowerCase();
    return operationsData.data.filter(
      (op) =>
        op.code.toLowerCase().includes(lower) ||
        op.ship.toLowerCase().includes(lower),
    );
  }, [operationsData, query]);

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
  };

  const getStatusBadge = (status: string): { light: string; dark: string } => {
    return statusBadgeStyles[status as OperationStatus] || statusBadgeStyles.Desconocido;
  };

  if (loading && !operationsData) {
    return (
      <div className="flex min-h-screen flex-col bg-[#f5f7f8] text-[#111827] dark:bg-[#0f1923] dark:text-[#f3f4f6]">
<main className="container mx-auto flex flex-grow flex-col px-4 py-8 sm:px-6 lg:px-8">
          <div className="mx-auto w-full max-w-6xl">
            <div className="flex items-center justify-center py-12">
              <div className="text-center">
                <div className="mb-4 h-8 w-8 animate-spin rounded-full border-4 border-[#0459af] border-t-transparent"></div>
                <p className="text-[#6b7280] dark:text-[#9ca3af]">Cargando operaciones...</p>
              </div>
            </div>
          </div>
        </main>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex min-h-screen flex-col bg-[#f5f7f8] text-[#111827] dark:bg-[#0f1923] dark:text-[#f3f4f6]">
<main className="container mx-auto flex flex-grow flex-col px-4 py-8 sm:px-6 lg:px-8">
          <div className="mx-auto w-full max-w-6xl">
            <div className="rounded-xl bg-red-50 p-6 dark:bg-red-900/20">
              <h3 className="mb-2 text-lg font-semibold text-red-800 dark:text-red-200">Error</h3>
              <p className="text-red-600 dark:text-red-300">{error}</p>
              <button
                onClick={fetchOperations}
                className="mt-4 rounded-lg bg-red-600 px-4 py-2 text-white hover:bg-red-700"
              >
                Reintentar
              </button>
            </div>
          </div>
        </main>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen flex-col bg-[#f5f7f8] text-[#111827] dark:bg-[#0f1923] dark:text-[#f3f4f6]">
<main className="container mx-auto flex flex-grow flex-col px-4 py-8 sm:px-6 lg:px-8">
        <div className="mx-auto w-full max-w-6xl">
          <header className="mb-6">
            <h2 className="text-3xl font-bold">
              Seleccionar Operación para Incidencia
            </h2>
            <p className="mt-1 text-[#6b7280] dark:text-[#9ca3af]">
              Gestiona las{" "}
              <span className="text-[#f97316] underline decoration-[#f97316]/50 decoration-2 underline-offset-2">
                operaciones marítimas
              </span>{" "}
              y registra incidencias.
            </p>
          </header>

          <section className="rounded-xl bg-white shadow-md dark:bg-[#1a2a3a]">
            <div className="flex flex-col items-center justify-between gap-4 border-b border-[#e5e7eb] p-6 dark:border-[#374151] sm:flex-row">
              <div className="relative w-full sm:max-w-xs">
                <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                  <span className="material-symbols-outlined text-[#6b7280] dark:text-[#9ca3af]">
                    search
                  </span>
                </div>
                <input
                  type="text"
                  placeholder="Buscar operación..."
                  className="w-full rounded-lg border border-[#e5e7eb] bg-[#f5f7f8] py-2 pl-10 pr-4 text-[#111827] focus:border-[#0459af] focus:outline-none focus:ring-[#0459af] dark:border-[#374151] dark:bg-[#0f1923] dark:text-[#f3f4f6]"
                  value={query}
                  onChange={(event) => setQuery(event.target.value)}
                />
              </div>
              <button
                type="button"
                className="flex items-center space-x-2 rounded-lg border border-[#e5e7eb] px-4 py-2 text-sm font-medium text-[#111827] transition-colors hover:bg-[#f5f7f8] dark:border-[#374151] dark:text-[#f3f4f6] dark:hover:bg-[#25384f]"
              >
                <span className="material-symbols-outlined text-base">
                  filter_list
                </span>
                <span>Filtros</span>
              </button>
            </div>

            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-[#e5e7eb] dark:divide-[#374151]">
                <thead className="bg-[#f5f7f8] text-xs font-medium uppercase tracking-wider text-[#6b7280] dark:bg-[#111b2c] dark:text-[#9ca3af]">
                  <tr>
                    <th scope="col" className="w-12 px-6 py-3 text-center">
                      <span className="sr-only">Seleccionar</span>
                    </th>
                    <th scope="col" className="px-6 py-3 text-left">
                      Código
                    </th>
                    <th scope="col" className="px-6 py-3 text-left">
                      Nombre del Buque
                    </th>
                    <th scope="col" className="px-6 py-3 text-left">
                      Estado
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#e5e7eb] bg-white dark:divide-[#374151] dark:bg-[#1a2a3a]">
                  {filteredOperations.map((operation) => {
                    const isSelected = selectedCode === operation.code;
                    const badge = getStatusBadge(operation.status);
                    return (
                      <tr
                        key={operation.code}
                        className={`cursor-pointer transition-colors hover:bg-[#f5f7f8] dark:hover:bg-[#25384f] ${isSelected ? "bg-[#0459af]/10 dark:bg-[#0459af]/20" : ""}`}
                        onClick={() => setSelectedCode(operation.code)}
                      >
                        <td className="px-6 py-4 text-center">
                          <input
                            type="radio"
                            name="select-operation"
                            className="h-4 w-4 cursor-pointer text-[#0459af] focus:ring-[#0459af]"
                            checked={isSelected}
                            onChange={() => setSelectedCode(operation.code)}
                          />
                        </td>
                        <td
                          className={`px-6 py-4 text-sm font-medium ${isSelected ? "text-[#0459af]" : ""}`}
                        >
                          {operation.code}
                        </td>
                        <td
                          className={`px-6 py-4 text-sm ${isSelected ? "text-[#0459af]" : "text-[#6b7280] dark:text-[#9ca3af]"}`}
                        >
                          {operation.ship}
                        </td>
                        <td className="px-6 py-4 text-sm">
                          <span
                            className={`inline-flex rounded-full px-2 py-1 text-xs font-semibold ${badge.light} ${badge.dark}`}
                          >
                            {operation.status}
                          </span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            <footer className="flex flex-col items-center justify-between gap-4 border-t border-[#e5e7eb] px-6 py-4 text-sm text-[#6b7280] dark:border-[#374151] dark:text-[#9ca3af] sm:flex-row">
              <p>
                Mostrando {filteredOperations.length} de {operationsData?.total || 0}{" "}
                operaciones
              </p>
              <div className="flex space-x-1">
                {operationsData && (
                  <>
                    <button
                      type="button"
                      onClick={() => handlePageChange(currentPage - 1)}
                      disabled={currentPage === 1}
                      className={`rounded-lg border px-3 py-1 transition-colors ${
                        currentPage === 1
                          ? "border-[#e5e7eb] text-[#9ca3af] cursor-not-allowed dark:border-[#374151] dark:text-[#6b7280]"
                          : "border-[#e5e7eb] text-[#374151] hover:bg-[#f5f7f8] dark:border-[#374151] dark:text-[#f3f4f6] dark:hover:bg-[#25384f]"
                      }`}
                    >
                      &lt;
                    </button>
                    
                    {Array.from({ length: operationsData.totalPages }, (_, i) => i + 1).map((pageNum) => {
                      const isActive = pageNum === currentPage;
                      return (
                        <button
                          key={pageNum}
                          type="button"
                          onClick={() => handlePageChange(pageNum)}
                          className={`rounded-lg border px-3 py-1 transition-colors ${
                            isActive
                              ? "border-[#0459af] bg-[#0459af] text-white"
                              : "border-[#e5e7eb] text-[#374151] hover:bg-[#f5f7f8] dark:border-[#374151] dark:text-[#f3f4f6] dark:hover:bg-[#25384f]"
                          }`}
                        >
                          {pageNum}
                        </button>
                      );
                    })}
                    
                    <button
                      type="button"
                      onClick={() => handlePageChange(currentPage + 1)}
                      disabled={currentPage === operationsData.totalPages}
                      className={`rounded-lg border px-3 py-1 transition-colors ${
                        currentPage === operationsData.totalPages
                          ? "border-[#e5e7eb] text-[#9ca3af] cursor-not-allowed dark:border-[#374151] dark:text-[#6b7280]"
                          : "border-[#e5e7eb] text-[#374151] hover:bg-[#f5f7f8] dark:border-[#374151] dark:text-[#f3f4f6] dark:hover:bg-[#25384f]"
                      }`}
                    >
                      &gt;
                    </button>
                  </>
                )}
              </div>
            </footer>
          </section>

          <div className="mt-8 flex flex-col justify-end gap-4 sm:flex-row">
            <Link
              href="/operaciones-maritimas"
              className="rounded-lg border border-[#e5e7eb] px-6 py-2 text-center text-sm font-semibold text-[#111827] transition-colors hover:bg-[#f5f7f8] dark:border-[#374151] dark:text-[#f3f4f6] dark:hover:bg-[#25384f]"
            >
              Cancelar / Volver
            </Link>
            <button
              type="button"
              disabled={!selectedCode}
              onClick={() => {
                if (!selectedCode) return;
                const params = new URLSearchParams({ op: selectedCode });
                router.push(
                  `/operaciones-maritimas/incidencias/nueva?${params.toString()}`,
                );
              }}
              className="rounded-lg bg-[#0459af] px-6 py-2 text-sm font-semibold text-white transition-colors hover:bg-[#0459af]/90 disabled:cursor-not-allowed disabled:bg-[#0459af]/40"
            >
              Registrar Incidencia
            </button>
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { Suspense, useState, useEffect } from 'react';
import Link from 'next/link';
import { useRouter, useSearchParams } from 'next/navigation';
import { getTripulantes } from '@/app/services/tripulante.service';

interface Tripulante {
  id_tripulante: string;
  id_empleado: string;
  disponibilidad: boolean;
  nacionalidad: string;
  empleado: {
    id_empleado: string;
    nombre: string;
    apellido: string;
    codigo: string;
  };
}

interface Buque {
  id_buque: string;
  matricula: string;
  nombre: string;
  capacidad: number;
  peso: number;
  ubicacion_actual: string;
}

function AsignarTripulacionContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const idBuque = searchParams.get('id_buque');

  const [tripulantes, setTripulantes] = useState<Tripulante[]>([]);
  const [buque, setBuque] = useState<Buque | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  // Esta pantalla solo construye la selección de tripulación y la pasa por query string

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Obtener tripulantes
        const todosLosTripulantes = await getTripulantes();
        console.log('Tripulantes recibidos:', todosLosTripulantes);

        // Filtrar solo los tripulantes disponibles
        const disponibles = todosLosTripulantes.filter(tripulante => tripulante.disponibilidad);
        console.log('Tripulantes disponibles:', disponibles);

        setTripulantes(disponibles);

        // Obtener datos del buque si hay id_buque
        if (idBuque) {
          const response = await fetch(`http://localhost:3001/monitoreo/buques/${idBuque}`);
          if (response.ok) {
            const buqueData = await response.json();
            setBuque(buqueData);
          }
        }
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Error desconocido';
        setError(`Error al cargar los datos: ${errorMessage}`);
        console.error('Error detallado:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [idBuque]);

  const [seleccionados, setSeleccionados] = useState<Set<string>>(new Set());
  const [paginaActual, setPaginaActual] = useState(1);
  const ELEMENTOS_POR_PAGINA = 10;

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col">
<main className="flex-1 container mx-auto p-6">
          <div className="bg-white dark:bg-slate-800 rounded-lg shadow-lg p-6">
            <p>Cargando tripulantes...</p>
          </div>
        </main>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex flex-col">
<main className="flex-1 container mx-auto p-6">
          <div className="bg-white dark:bg-slate-800 rounded-lg shadow-lg p-6 text-red-500">
            <p>{error}</p>
          </div>
        </main>
      </div>
    );
  }

  const toggleSeleccion = (id: string) => {
    const nuevosSeleccionados = new Set(seleccionados);
    if (nuevosSeleccionados.has(id)) {
      nuevosSeleccionados.delete(id);
    } else {
      nuevosSeleccionados.add(id);
    }
    setSeleccionados(nuevosSeleccionados);
  };

  // Paginación
  const totalPaginas = Math.ceil(tripulantes.length / ELEMENTOS_POR_PAGINA);
  const indiceInicio = (paginaActual - 1) * ELEMENTOS_POR_PAGINA;
  const indiceFin = indiceInicio + ELEMENTOS_POR_PAGINA;
  const tripulantesPagina = tripulantes.slice(indiceInicio, indiceFin);

  const irAPagina = (pagina: number) => {
    if (pagina >= 1 && pagina <= totalPaginas) {
      setPaginaActual(pagina);
    }
  };

  // Restaura el comportamiento original: pasar IDs por query param y volver a /operaciones-maritimas/nueva
  const handleAsignar = () => {
    const params = new URLSearchParams(searchParams.toString());

    if (seleccionados.size > 0) {
      params.set('tripulacion', Array.from(seleccionados).join(','));
    } else {
      params.delete('tripulacion');
    }

    router.push(`/operaciones-maritimas/nueva?${params.toString()}`);
  };
  return (
    <div className="min-h-screen flex flex-col">
<main className="flex-1 container mx-auto p-6">
        <div className="bg-white dark:bg-slate-800 rounded-lg shadow-lg p-6">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h1 className="text-2xl font-bold text-gray-800 dark:text-white">
                Asignar Tripulación
              </h1>
              {idBuque && (
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  Buque ID: {idBuque}
                </p>
              )}
            </div>
            <Link
              href="/operaciones-maritimas/nueva"
              className="px-4 py-2 bg-gray-200 dark:bg-slate-700 text-gray-800 dark:text-white rounded-md hover:bg-gray-300 dark:hover:bg-slate-600 transition-colors"
            >
              Volver
            </Link>
          </div>

          <div className="overflow-x-auto">
            {tripulantes.length === 0 ? (
              <div className="p-6 text-center text-gray-500 dark:text-gray-300">
                No hay tripulantes disponibles en este momento.
              </div>
            ) : (
              <table className="min-w-full bg-white dark:bg-slate-800 rounded-lg overflow-hidden">
                <thead className="bg-gray-50 dark:bg-slate-700">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                      Seleccionar
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                      Código
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                      Nombre Completo
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                      Nacionalidad
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider">
                      Estado
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-200 dark:divide-slate-700">
                  {tripulantesPagina.map((tripulante) => (
                    <tr
                      key={tripulante.id_tripulante}
                      className={`hover:bg-gray-50 dark:hover:bg-slate-700 ${seleccionados.has(tripulante.id_tripulante) ? 'bg-blue-50 dark:bg-blue-900/30' : ''
                        }`}
                    >
                      <td className="px-6 py-4 whitespace-nowrap">
                        <input
                          type="checkbox"
                          className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
                          checked={seleccionados.has(tripulante.id_tripulante)}
                          onChange={() => toggleSeleccion(tripulante.id_tripulante)}
                        />
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900 dark:text-white">
                        {tripulante.empleado.codigo}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-300">
                        {tripulante.empleado.nombre} {tripulante.empleado.apellido}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-300">
                        {tripulante.nacionalidad}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${tripulante.disponibilidad
                            ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200'
                            : 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200'
                          }`}>
                          {tripulante.disponibilidad ? 'Disponible' : 'No disponible'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>

          {/* Paginación */}
          {totalPaginas > 1 && (
            <div className="mt-4 flex items-center justify-between">
              <p className="text-sm text-gray-600 dark:text-gray-400">
                Mostrando {indiceInicio + 1}–{Math.min(indiceFin, tripulantes.length)} de {tripulantes.length} tripulantes
                {seleccionados.size > 0 && (
                  <span className="ml-2 text-blue-600 dark:text-blue-400">
                    · {seleccionados.size} seleccionado{seleccionados.size !== 1 ? 's' : ''}
                  </span>
                )}
              </p>
              <div className="flex items-center gap-1">
                <button
                  onClick={() => irAPagina(1)}
                  disabled={paginaActual === 1}
                  className="px-2 py-1 rounded text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-slate-700 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                  aria-label="Primera página"
                >
                  «
                </button>
                <button
                  onClick={() => irAPagina(paginaActual - 1)}
                  disabled={paginaActual === 1}
                  className="px-2 py-1 rounded text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-slate-700 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                  aria-label="Página anterior"
                >
                  ‹
                </button>
                {Array.from({ length: totalPaginas }, (_, i) => i + 1)
                  .filter(p => p === 1 || p === totalPaginas || Math.abs(p - paginaActual) <= 2)
                  .reduce<(number | '...')[]>((acc, p, idx, arr) => {
                    if (idx > 0 && (p as number) - (arr[idx - 1] as number) > 1) acc.push('...');
                    acc.push(p);
                    return acc;
                  }, [])
                  .map((item, idx) =>
                    item === '...' ? (
                      <span key={`ellipsis-${idx}`} className="px-2 py-1 text-sm text-gray-400">…</span>
                    ) : (
                      <button
                        key={item}
                        onClick={() => irAPagina(item as number)}
                        className={`px-3 py-1 rounded text-sm font-medium transition-colors ${paginaActual === item
                            ? 'bg-blue-600 text-white'
                            : 'text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-slate-700'
                          }`}
                      >
                        {item}
                      </button>
                    )
                  )}
                <button
                  onClick={() => irAPagina(paginaActual + 1)}
                  disabled={paginaActual === totalPaginas}
                  className="px-2 py-1 rounded text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-slate-700 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                  aria-label="Página siguiente"
                >
                  ›
                </button>
                <button
                  onClick={() => irAPagina(totalPaginas)}
                  disabled={paginaActual === totalPaginas}
                  className="px-2 py-1 rounded text-sm text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-slate-700 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                  aria-label="Última página"
                >
                  »
                </button>
              </div>
            </div>
          )}

          <div className="mt-6 flex justify-end">
            <button
              onClick={handleAsignar}
              disabled={seleccionados.size === 0}
              className={`px-6 py-2 rounded-md text-white font-medium ${seleccionados.size > 0
                  ? 'bg-blue-600 hover:bg-blue-700'
                  : 'bg-gray-400 cursor-not-allowed'
                } transition-colors`}
            >
              Asignar Tripulantes ({seleccionados.size})
            </button>
          </div>
        </div>
      </main>
    </div>
  );
}

export default function AsignarTripulacionPage() {
  return (
    <Suspense
      fallback={
        <div className="flex min-h-screen flex-col">
          <main className="container mx-auto flex-1 p-6">Cargando...</main>
        </div>
      }
    >
      <AsignarTripulacionContent />
    </Suspense>
  );
}

