"use client";

import { useEffect, useRef, useState } from "react";
import L from "leaflet";
import "leaflet/dist/leaflet.css";

// Arreglar iconos por defecto de Leaflet en Next.js
if (typeof window !== 'undefined') {
  delete (L.Icon.Default.prototype as any)._getIconUrl;
  L.Icon.Default.mergeOptions({
    iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon-2x.png',
    iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon.png',
    shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png',
  });
}

interface Asset {
  id: string;
  code: string;
  type: 'container' | 'vehicle' | 'ship';
  position: [number, number];
  status: string;
  statusColor: string;
  icon: string;
  lastUpdate: string;
  speed: string;
  temp: string;
}

interface MapComponentProps {
  assets: Asset[];
  selectedAsset: Asset | null;
  onAssetSelect: (asset: Asset | null) => void;
  onMapReady: (map: any) => void;
}

// Crear iconos personalizados para marcadores
function createCustomIcon(asset: Asset) {
  const isAlert = asset.status === 'Alerta';

  return L.divIcon({
    html: `
      <div class="custom-marker ${isAlert ? 'alert' : ''}" style="
        width: 40px;
        height: 40px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        box-shadow: 0 4px 6px rgba(0,0,0,0.2);
        cursor: pointer;
        transition: transform 0.2s;
        background-color: ${asset.statusColor};
        ${isAlert ? 'animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;' : ''}
      ">
        <span class="material-symbols-outlined" style="font-size: 24px; color: white;">${asset.icon}</span>
      </div>
      <style>
        @keyframes pulse {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.7; }
        }
        .custom-marker:hover {
          transform: scale(1.15);
        }
      </style>
    `,
    className: '',
    iconSize: [40, 40],
    iconAnchor: [20, 20],
  });
}

export default function MapComponent({ assets, selectedAsset, onAssetSelect, onMapReady }: MapComponentProps) {
  const [mapLayer, setMapLayer] = useState<'street' | 'satellite'>('street');
  const [showInfoPanel, setShowInfoPanel] = useState(false);
  const mapRef = useRef<L.Map | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const markersRef = useRef<L.Marker[]>([]);
  const polylineRef = useRef<L.Polyline | null>(null);
  const tileLayerRef = useRef<L.TileLayer | null>(null);
  const initializedRef = useRef(false);

  // Ruta de ejemplo
  const routePath: [number, number][] = [
    [-12.046374, -77.042793],
    [-11.956789, -77.082345],
    [-11.923456, -77.134567],
    [-12.056789, -77.182891]
  ];

  // Inicializar mapa
  useEffect(() => {
    if (!containerRef.current || initializedRef.current) return;

    // Marcar como inicializado inmediatamente
    initializedRef.current = true;

    // Crear mapa
    const map = L.map(containerRef.current, {
      center: [-12.046374, -77.042793],
      zoom: 10,
      zoomControl: false,
    });

    mapRef.current = map;

    // Agregar capa base
    const tileLayer = L.tileLayer(
      'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
      {
        attribution: '© OpenStreetMap contributors',
        maxZoom: 19,
      }
    );
    tileLayer.addTo(map);
    tileLayerRef.current = tileLayer;

    // Agregar polyline
    const polyline = L.polyline(routePath, {
      color: '#ff8c00',
      weight: 4,
      opacity: 0.7,
      dashArray: '10, 10',
    });
    polyline.addTo(map);
    polylineRef.current = polyline;

    // Notificar que el mapa está listo
    onMapReady(map);

    // Cleanup
    return () => {
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
        initializedRef.current = false;
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Actualizar marcadores cuando cambian los assets
  useEffect(() => {
    if (!mapRef.current) return;

    // Limpiar marcadores anteriores
    markersRef.current.forEach(marker => marker.remove());
    markersRef.current = [];

    // Agregar nuevos marcadores
    assets.forEach(asset => {
      const marker = L.marker(asset.position, {
        icon: createCustomIcon(asset),
      });

      marker.on('click', () => {
        onAssetSelect(asset);
      });

      marker.addTo(mapRef.current!);
      markersRef.current.push(marker);
    });
  }, [assets, onAssetSelect]);

  // Actualizar capa de tiles cuando cambia el tipo
  useEffect(() => {
    if (!mapRef.current || !tileLayerRef.current) return;

    tileLayerRef.current.remove();

    const newTileLayer = L.tileLayer(
      mapLayer === 'street'
        ? 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png'
        : 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
      {
        attribution: mapLayer === 'street' ? '© OpenStreetMap contributors' : '© Esri',
        maxZoom: 19,
      }
    );
    newTileLayer.addTo(mapRef.current);
    tileLayerRef.current = newTileLayer;
  }, [mapLayer]);

  // Centrar en asset seleccionado
  useEffect(() => {
    if (selectedAsset && mapRef.current) {
      mapRef.current.flyTo(selectedAsset.position, 13, { duration: 1.5 });
    }
  }, [selectedAsset]);

  useEffect(() => {
    setShowInfoPanel(selectedAsset !== null);
  }, [selectedAsset]);

  const handleCenterMap = () => {
    if (mapRef.current) {
      mapRef.current.flyTo([-12.046374, -77.042793], 10, { duration: 1.5 });
    }
  };

  const handleToggleLayer = () => {
    setMapLayer(prev => prev === 'street' ? 'satellite' : 'street');
  };

  const closeInfoPanel = () => {
    setShowInfoPanel(false);
    onAssetSelect(null);
  };

  return (
    <>
      {/* Contenedor del mapa */}
      <div ref={containerRef} style={{ width: '100%', height: '100%', zIndex: 0 }} />

      {/* Controles del mapa */}
      <div className="absolute top-4 right-4 flex flex-col gap-2 z-[1000]">
        <button
          onClick={() => mapRef.current?.zoomIn()}
          className="flex h-10 w-10 items-center justify-center rounded-lg bg-white shadow-md text-slate-700 hover:bg-gray-50"
        >
          <span className="material-symbols-outlined">add</span>
        </button>
        <button
          onClick={() => mapRef.current?.zoomOut()}
          className="flex h-10 w-10 items-center justify-center rounded-lg bg-white shadow-md text-slate-700 hover:bg-gray-50"
        >
          <span className="material-symbols-outlined">remove</span>
        </button>
        <button
          onClick={handleToggleLayer}
          className="mt-2 flex h-10 w-10 items-center justify-center rounded-lg bg-white shadow-md text-slate-700 hover:bg-gray-50"
          title="Cambiar capa"
        >
          <span className="material-symbols-outlined">layers</span>
        </button>
        <button
          onClick={handleCenterMap}
          className="flex h-10 w-10 items-center justify-center rounded-lg bg-white shadow-md text-slate-700 hover:bg-gray-50"
        >
          <span className="material-symbols-outlined">my_location</span>
        </button>
      </div>

      {/* Panel de información */}
      {showInfoPanel && selectedAsset && (
        <div className="absolute bottom-0 left-1/2 -translate-x-1/2 mb-4 w-full max-w-lg z-[1000]">
          <div className="rounded-xl shadow-2xl bg-white p-6 m-4">
            <div className="flex items-start justify-between">
              <div className="flex items-center gap-4">
                <div 
                  className="text-primary flex items-center justify-center rounded-lg bg-primary/20 shrink-0 size-12"
                >
                  <span className="material-symbols-outlined">{selectedAsset.icon}</span>
                </div>
                <div>
                  <h3 className="text-lg font-bold text-slate-900">{selectedAsset.code}</h3>
                  <div className="flex items-center gap-2">
                    <div 
                      className="size-2 rounded-full" 
                      style={{ backgroundColor: selectedAsset.statusColor }}
                    ></div>
                    <p 
                      className="text-sm font-medium" 
                      style={{ color: selectedAsset.statusColor }}
                    >
                      {selectedAsset.status}
                    </p>
                  </div>
                </div>
              </div>
              <button 
                onClick={closeInfoPanel}
                className="text-slate-500 hover:text-slate-900"
              >
                <span className="material-symbols-outlined">close</span>
              </button>
            </div>

            <div className="grid grid-cols-2 gap-4 mt-6 text-sm">
              <div>
                <p className="text-slate-500">Última Actualización</p>
                <p className="font-medium text-slate-900">{selectedAsset.lastUpdate}</p>
              </div>
              <div>
                <p className="text-slate-500">Velocidad</p>
                <p className="font-medium text-slate-900">{selectedAsset.speed}</p>
              </div>
              <div>
                <p className="text-slate-500">Ubicación Actual</p>
                <p className="font-medium text-slate-900">
                  {selectedAsset.position[0].toFixed(4)}° S, {Math.abs(selectedAsset.position[1]).toFixed(4)}° W
                </p>
              </div>
              <div>
                <p className="text-slate-500">Temperatura</p>
                <p className="font-medium text-slate-900">{selectedAsset.temp}</p>
              </div>
            </div>

            <div className="mt-6">
              <button className="flex w-full cursor-pointer items-center justify-center overflow-hidden rounded-lg h-11 bg-primary text-white gap-2 text-sm font-bold leading-normal tracking-[0.015em] min-w-0 px-4 hover:bg-primary/90">
                <span className="material-symbols-outlined text-base">timeline</span>
                <span>Ver Ruta Histórica</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import "@/app/leaflet.css";

const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:3001"; 

// Arreglar iconos por defecto de Leaflet en Next.js
if (typeof window !== 'undefined') {
  delete (L.Icon.Default.prototype as any)._getIconUrl;
  L.Icon.Default.mergeOptions({
    iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon-2x.png',
    iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon.png',
    shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png',
  });
}

interface PosicionGPS {
  id: string;
  code: string;
  type: "container" | "vehicle" | "ship";
  position: [number, number];
  status: string;
  statusColor: string;
  icon: string;
  lastUpdate: string;
  speed?: string;
  temp?: string;
}

interface MapaGPSDashboardProps {
  height?: string;
}

// Crear iconos personalizados para marcadores
function createCustomIcon(asset: PosicionGPS) {
  return L.divIcon({
    html: `
      <div style="
        width: 30px;
        height: 30px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        box-shadow: 0 2px 8px rgba(0,0,0,0.3);
        cursor: pointer;
        transition: transform 0.2s;
        background-color: ${asset.statusColor};
      ">
        <span style="font-size: 16px; color: white;">
          ${asset.type === "container" ? "📦" : asset.type === "vehicle" ? "🚛" : "🚢"}
        </span>
      </div>
    `,
    className: '',
    iconSize: [30, 30],
    iconAnchor: [15, 15],
  });
}

export default function MapaGPSDashboard({ height = "400px" }: MapaGPSDashboardProps) {
  const [posiciones, setPosiciones] = useState<PosicionGPS[]>([]);
  const [loading, setLoading] = useState(true);
  const mapRef = useRef<L.Map | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const markersRef = useRef<L.Marker[]>([]);
  const initializedRef = useRef(false);

  // Cargar posiciones GPS
  useEffect(() => {
    const fetchPosiciones = async () => {
        try {
        const response = await fetch(`${API_URL}/monitoreo/gps/posiciones`);
        console.log("GPS status", response.status);
        if (response.ok) {
            const data = await response.json();
            console.log("GPS data", data);
            setPosiciones(data);
        }
        setLoading(false);
        } catch (error) {
        console.error("Error al cargar posiciones GPS:", error);
        setLoading(false);
        }
    };

    fetchPosiciones();
        const interval = setInterval(fetchPosiciones, 30000);
        return () => clearInterval(interval);
    }, []);

  // Inicializar mapa
  useEffect(() => {
    if (initializedRef.current) return;

    let cancelled = false;

    const initMap = () => {
      if (cancelled || initializedRef.current) return;

      if (!containerRef.current) {
        // Esperar al siguiente frame hasta que el ref exista
        requestAnimationFrame(initMap);
        return;
      }

      initializedRef.current = true;
      console.log("Inicializando mapa dashboard");

      const map = L.map(containerRef.current, {
        center: [-12.046374, -77.042793],
        zoom: 10,
        zoomControl: false,
      });

      mapRef.current = map;

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '© OpenStreetMap contributors',
        maxZoom: 19,
      }).addTo(map);

      // Forzar a Leaflet a recalcular el tamaño del mapa una vez montado el layout
      setTimeout(() => {
        if (mapRef.current) {
          mapRef.current.invalidateSize();
        }
      }, 200);
    };

    initMap();

    return () => {
      cancelled = true;
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
      initializedRef.current = false;
    };
  }, []);

  // Actualizar marcadores cuando cambian las posiciones
  useEffect(() => {
    if (!mapRef.current || posiciones.length === 0) return;
    console.log("Dibujando marcadores en el mapa", posiciones.length);
    // Limpiar marcadores anteriores
    markersRef.current.forEach(marker => marker.remove());
    markersRef.current = [];

    // Agregar nuevos marcadores
    posiciones.forEach(posicion => {
      const marker = L.marker(posicion.position, {
        icon: createCustomIcon(posicion),
      });

      // Crear popup con información
      const popupContent = `
        <div style="min-width: 200px; padding: 8px;">
          <div style="display: flex; align-items: center; gap: 8px; border-bottom: 1px solid #e5e7eb; padding-bottom: 8px; margin-bottom: 8px;">
            <span style="font-size: 20px; color: ${posicion.statusColor};">
              ${posicion.type === "container" ? "📦" : posicion.type === "vehicle" ? "🚛" : "🚢"}
            </span>
            <div>
              <p style="font-size: 14px; font-weight: 600; margin: 0;">${posicion.code}</p>
              <p style="font-size: 12px; color: #6b7280; margin: 0;">
                ${posicion.type === "container" ? "Contenedor" : posicion.type === "vehicle" ? "Vehículo" : "Buque"}
              </p>
            </div>
          </div>
          <div style="font-size: 12px; line-height: 1.5;">
            <div style="display: flex; justify-content: space-between; margin-bottom: 4px;">
              <span style="color: #6b7280;">Estado:</span>
              <span style="font-weight: 500; color: ${posicion.statusColor};">${posicion.status}</span>
            </div>
            ${posicion.speed && posicion.speed !== "N/A" ? `
            <div style="display: flex; justify-content: space-between; margin-bottom: 4px;">
              <span style="color: #6b7280;">Velocidad:</span>
              <span style="font-weight: 500;">${posicion.speed}</span>
            </div>
            ` : ''}
            ${posicion.temp && posicion.temp !== "N/A" ? `
            <div style="display: flex; justify-content: space-between; margin-bottom: 4px;">
              <span style="color: #6b7280;">Temperatura:</span>
              <span style="font-weight: 500;">${posicion.temp}</span>
            </div>
            ` : ''}
            <div style="display: flex; justify-content: space-between;">
              <span style="color: #6b7280;">Última act.:</span>
              <span style="font-weight: 500;">${new Date(posicion.lastUpdate).toLocaleTimeString("es-PE", { hour: "2-digit", minute: "2-digit" })}</span>
            </div>
          </div>
        </div>
      `;

      marker.bindPopup(popupContent);
      marker.addTo(mapRef.current!);
      markersRef.current.push(marker);
    });

    // Ajustar el zoom para mostrar todos los marcadores
    if (posiciones.length > 0) {
      const bounds = L.latLngBounds(posiciones.map(p => p.position as [number, number]));
      mapRef.current.fitBounds(bounds, { padding: [50, 50] });

      // Recalcular tamaño tras ajustar el viewport
      setTimeout(() => {
        if (mapRef.current) {
          mapRef.current.invalidateSize();
        }
      }, 200);
    }
  }, [posiciones]);

  if (loading) {
    return (
      <div 
        style={{ height }} 
        className="flex items-center justify-center bg-zinc-100 dark:bg-zinc-800 rounded-lg"
      >
        <div className="flex flex-col items-center gap-2">
          <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent"></div>
          <p className="text-sm text-zinc-600 dark:text-zinc-400">Cargando mapa...</p>
        </div>
      </div>
    );
  }

  if (posiciones.length === 0) {
    return (
      <div 
        style={{ height }} 
        className="flex items-center justify-center bg-zinc-100 dark:bg-zinc-800 rounded-lg"
      >
        <div className="text-center">
          <span className="material-symbols-outlined text-4xl text-zinc-400">location_off</span>
          <p className="mt-2 text-sm text-zinc-600 dark:text-zinc-400">
            No hay datos GPS disponibles
          </p>
        </div>
      </div>
    );
  }

  return (
  <div style={{ height }} className="relative rounded-lg overflow-hidden">
    <div
      ref={containerRef}
      style={{ width: "100%", height: "100%" }}
    />
  </div>
    );
}

